// <auto-generated companion /> — tag/name queries mirroring <c>GameWorld::QueryGameObjects</c>.
#nullable enable

namespace Spark.Bindings;

/// <summary>Collects <see cref="GameObject"/> handles matching a query filter.</summary>
public sealed class GameObjectQuery
{
    private readonly GameWorld _world;

    public GameObjectQuery(GameWorld world) => _world = world;

    /// <summary>Returns total matches; fills <paramref name="buffer"/> up to its length.</summary>
    public int CollectWithTag(string tag, Span<GameObject> buffer, bool includeInactive = false)
    {
        if (buffer.IsEmpty)
        {
            unsafe
            {
                uint totalOnly = 0;
                InteropUtf8.WithUtf8(tag, ptr =>
                {
                    totalOnly = Native.spark_world_query_collect_by_tag(
                        InteropPtr.World(_world.Handle),
                        (sbyte*)ptr,
                        includeInactive ? 1 : 0,
                        null,
                        0);
                });
                return (int)totalOnly;
            }
        }

        unsafe
        {
            var nativeBuffer = stackalloc SparkGameObject*[buffer.Length];
            uint total;
            byte[] tagBytes = System.Text.Encoding.UTF8.GetBytes(tag + "\0");
            fixed (byte* tagPtr = tagBytes)
            {
                total = Native.spark_world_query_collect_by_tag(
                    InteropPtr.World(_world.Handle),
                    (sbyte*)tagPtr,
                    includeInactive ? 1 : 0,
                    nativeBuffer,
                    (uint)buffer.Length);
            }

            int copy = (int)Math.Min(total, (uint)buffer.Length);
            for (int i = 0; i < copy; i++)
            {
                buffer[i] = new GameObject(InteropPtr.From(nativeBuffer[i]));
            }

            return (int)total;
        }
    }
}
